/* logger.c */
#include <stdio.h>

int total_events = 0;          /* file scope, static storage, EXTERNAL linkage. */
static int errors = 0;         /* file scope, static storage, INTERNAL linkage. */

void log_event(const char *msg) {
    int local = 0;             /* block scope, automatic: new each call. */
    static int calls = 0;      /* block scope, static: kept between calls. */
    local++;
    calls++;
    total_events++;
    printf("%s (local=%d, calls=%d)\n", msg, local, calls);
}
/* After three calls: local is always 1, calls is 3. */
```

| Declaration | Scope | Lifetime | Other files? |
|---|---|---|---|
| `int x;` in a function. | block. | automatic. | no. |
| `static int x;` in a function. | block. | whole program. | no. |
| `int x;` at file level. | file. | whole program. | yes (extern). |
| `static int x;` at file level. | file. | whole program. | no. |

